    PostContentRequest.add_member(:bot_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BotName, location_name: 'botName', traits: {"smithy.api#documentation" => "<p>Name of the Amazon Lex bot.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    PostContentRequest.add_member(:bot_alias, Smithy::Schema::Shapes::ShapeRef.new(shape: BotAlias, location_name: 'botAlias', traits: {"smithy.api#documentation" => "<p>Alias of the Amazon Lex bot.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    PostContentRequest.add_member(:user_id, Smithy::Schema::Shapes::ShapeRef.new(shape: UserId, location_name: 'userId', traits: {"smithy.api#documentation" => "<p>The ID of the client application user. Amazon Lex uses this to identify a\n      user's conversation with your bot. At runtime, each request must contain\n      the <code>userID</code> field.</p>\n         <p>To decide the user ID to use for your application, consider the\n      following factors.</p>\n         <ul>\n            <li>\n               <p>The <code>userID</code> field must not contain any personally\n          identifiable information of the user, for example, name, personal\n          identification numbers, or other end user personal information.</p>\n            </li>\n            <li>\n               <p>If you want a user to start a conversation on one device and\n          continue on another device, use a user-specific identifier.</p>\n            </li>\n            <li>\n               <p>If you want the same user to be able to have two independent\n          conversations on two different devices, choose a device-specific\n          identifier.</p>\n            </li>\n            <li>\n               <p>A user can't have two independent conversations with two different\n          versions of the same bot. For example, a user can't have a\n          conversation with the PROD and BETA versions of the same bot. If you\n          anticipate that a user will need to have conversation with two\n          different versions, for example, while testing, include the bot alias\n          in the user ID to separate the two conversations.</p>\n            </li>\n         </ul>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    PostContentRequest.add_member(:session_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: SynthesizedJsonAttributesString, location_name: 'sessionAttributes', traits: {"smithy.api#documentation" => "<p>You pass this value as the <code>x-amz-lex-session-attributes</code>\n      HTTP header.</p>\n         <p>Application-specific information passed between Amazon Lex and a client\n      application. The value must be a JSON serialized and base64 encoded map\n      with string keys and values. The total size of the\n        <code>sessionAttributes</code> and <code>requestAttributes</code>\n      headers is limited to 12 KB.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/lex/latest/dg/context-mgmt.html#context-mgmt-session-attribs\">Setting Session Attributes</a>.</p>", "smithy.api#httpHeader" => "x-amz-lex-session-attributes"}))
    PostContentRequest.add_member(:request_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: SynthesizedJsonAttributesString, location_name: 'requestAttributes', traits: {"smithy.api#documentation" => "<p>You pass this value as the <code>x-amz-lex-request-attributes</code>\n      HTTP header.</p>\n         <p>Request-specific information passed between Amazon Lex and a client\n      application. The value must be a JSON serialized and base64 encoded map\n      with string keys and values. The total size of the\n        <code>requestAttributes</code> and <code>sessionAttributes</code>\n      headers is limited to 12 KB.</p>\n         <p>The namespace <code>x-amz-lex:</code> is reserved for special\n      attributes. Don't create any request attributes with the prefix\n        <code>x-amz-lex:</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/lex/latest/dg/context-mgmt.html#context-mgmt-request-attribs\">Setting Request Attributes</a>.</p>", "smithy.api#httpHeader" => "x-amz-lex-request-attributes"}))
    PostContentRequest.add_member(:content_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HttpContentType, location_name: 'contentType', traits: {"smithy.api#documentation" => "<p> You pass this value as the <code>Content-Type</code> HTTP header. </p>\n         <p> Indicates the audio format or text. The header value must start with\n      one of the following prefixes: </p>\n         <ul>\n            <li>\n               <p>PCM format, audio data must be in little-endian byte order.</p>\n               <ul>\n                  <li>\n                     <p>audio/l16; rate=16000; channels=1</p>\n                  </li>\n                  <li>\n                     <p>audio/x-l16; sample-rate=16000; channel-count=1</p>\n                  </li>\n                  <li>\n                     <p>audio/lpcm; sample-rate=8000; sample-size-bits=16;\n              channel-count=1; is-big-endian=false </p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>Opus format</p>\n               <ul>\n                  <li>\n                     <p>audio/x-cbr-opus-with-preamble; preamble-size=0;\n              bit-rate=256000; frame-size-milliseconds=4</p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>Text format</p>\n               <ul>\n                  <li>\n                     <p>text/plain; charset=utf-8</p>\n                  </li>\n               </ul>\n            </li>\n         </ul>", "smithy.api#httpHeader" => "Content-Type", "smithy.api#required" => {}}))
    PostContentRequest.add_member(:accept, Smithy::Schema::Shapes::ShapeRef.new(shape: Accept, location_name: 'accept', traits: {"smithy.api#documentation" => "<p> You pass this value as the <code>Accept</code> HTTP header. </p>\n         <p> The message Amazon Lex returns in the response can be either text or\n      speech based on the <code>Accept</code> HTTP header value in the request. </p>\n         <ul>\n            <li>\n               <p> If the value is <code>text/plain; charset=utf-8</code>, Amazon Lex\n          returns text in the response. </p>\n            </li>\n            <li>\n               <p> If the value begins with <code>audio/</code>, Amazon Lex returns\n          speech in the response. Amazon Lex uses Amazon Polly to generate the speech\n          (using the configuration you specified in the <code>Accept</code>\n          header). For example, if you specify <code>audio/mpeg</code> as the\n          value, Amazon Lex returns speech in the MPEG format.</p>\n            </li>\n            <li>\n               <p>If the value is <code>audio/pcm</code>, the speech returned is\n            <code>audio/pcm</code> in 16-bit, little endian format.\n          </p>\n            </li>\n            <li>\n               <p>The following are the accepted values:</p>\n               <ul>\n                  <li>\n                     <p>audio/mpeg</p>\n                  </li>\n                  <li>\n                     <p>audio/ogg</p>\n                  </li>\n                  <li>\n                     <p>audio/pcm</p>\n                  </li>\n                  <li>\n                     <p>text/plain; charset=utf-8</p>\n                  </li>\n                  <li>\n                     <p>audio/* (defaults to mpeg)</p>\n                  </li>\n               </ul>\n            </li>\n         </ul>", "smithy.api#httpHeader" => "Accept"}))
    PostContentRequest.add_member(:input_stream, Smithy::Schema::Shapes::ShapeRef.new(shape: BlobStream, location_name: 'inputStream', traits: {"smithy.api#documentation" => "<p> User input in PCM or Opus audio format or text format as described in\n      the <code>Content-Type</code> HTTP header. </p>\n         <p>You can stream audio data to Amazon Lex or you can create a local buffer\n      that captures all of the audio data before sending. In general, you get\n      better performance if you stream audio data rather than buffering the data\n      locally.</p>", "smithy.api#httpPayload" => {}, "smithy.api#required" => {}}))
    PostContentRequest.add_member(:active_contexts, Smithy::Schema::Shapes::ShapeRef.new(shape: SynthesizedJsonActiveContextsString, location_name: 'activeContexts', traits: {"smithy.api#documentation" => "<p>A list of contexts active for the request. A context can be activated\n      when a previous intent is fulfilled, or by including the context in the\n      request,</p>\n         <p>If you don't specify a list of contexts, Amazon Lex will use the current\n      list of contexts for the session. If you specify an empty list, all\n      contexts for the session are cleared.</p>", "smithy.api#httpHeader" => "x-amz-lex-active-contexts"}))
