    PostContentResponse.add_member(:active_contexts, Smithy::Schema::Shapes::ShapeRef.new(shape: SynthesizedJsonActiveContextsString, location_name: 'activeContexts', traits: {"smithy.api#documentation" => "<p>A list of active contexts for the session. A context can be set when\n      an intent is fulfilled or by calling the <code>PostContent</code>,\n        <code>PostText</code>, or <code>PutSession</code> operation.</p>\n         <p>You can use a context to control the intents that can follow up an\n      intent, or to modify the operation of your application.</p>", "smithy.api#httpHeader" => "x-amz-lex-active-contexts"}))
